  String get usageAnalyticsChangeHint;

  /// First-launch sheet link that opens the privacy notice in the browser (the notice itself is in English). Not part of the versioned wording.
  ///
  /// In en, this message translates to:
  /// **'Privacy notice'**
  String get usageAnalyticsNoticeLink;

